from pathlib import Path

path = Path('/home/ubuntu/nexbet-black-gold/client/src/App.tsx')
source = path.read_text()
start = source.index('function Casino(){')
end = source.index('\nexport default App;', start)
replacement = """function Casino(){ const [filter,setFilter]=useState(\"All games\"); const [query,setQuery]=useState(\"\"); const categoryFor=(name:string)=>{const n=name.toLowerCase(); if(n.includes(\"aviator\")||n.includes(\"spaceman\")||n.includes(\"jet\")) return \"Crash\"; if(n.includes(\"bottle\")||n.includes(\"ball\")||n.includes(\"slots\")) return \"Table\"; if(n.includes(\"kick\")||n.includes(\"football\")) return \"Live\"; return \"Hot\"}; const filtered=useMemo(()=>games.filter(([n])=>(filter===\"All games\"||categoryFor(n)===filter)&&n.toLowerCase().includes(query.toLowerCase())),[filter,query]); return <><Header onMenu={()=>document.body.classList.toggle(\"menu-open\")}/><main className=\"wrap casino-page\"><div className=\"casino-hero\"><img src={casinoFeature}/><div><span className=\"eyebrow\">HotBet originals</span><h1>Play beyond<br/><em>the odds.</em></h1><p>Quick games, bright wins, and a lobby built for the next round.</p></div></div><div className=\"casino-toolbar\"><div className=\"casino-tabs\">{[\"All games\",\"Hot\",\"Crash\",\"Table\",\"Live\"].map(x=><button key={x} className={filter===x?\"active\":\"\"} aria-pressed={filter===x} onClick={()=>setFilter(x)}>{x}</button>)}</div><label className=\"search-box\"><Search size={15}/><input placeholder=\"Search games\" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><section className=\"game-grid\">{[...filtered,...filtered,...filtered].map(([name,img],i)=><Link href={`/games/${slugify(name)}`} className=\"game-tile\" key={`${name}-${i}`}><img src={img}/><div><b>{name}</b><span>Play now <ChevronRight size={12}/></span></div></Link>)}</section>{filtered.length===0&&<section className=\"panel simple-card\"><h3>No games found</h3><p className=\"muted\">Try another category or search term.</p></section>}</main><Footer/></> }\n"""
path.write_text(source[:start] + replacement + source[end:])
